mapper.select:


    inner join sys_user u on u.user_name = tperson.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tperson.del_flag = '0'
     and tperson.name like concat('%', #{name}, '%')
     and tperson.email = #{email}
     and tperson.address = #{address}
     and tperson.phone = #{phone}
     and tperson.company_name like concat('%', #{companyName}, '%')
     and tperson.sex = #{sex}


${params.dataScope}
order by id desc
